//! `@NODE@` — generated by `nros new` from the `talker` template.
//!
//! Publishes `std_msgs/String` (`Hello World: N`) on `/chatter` once a second.
//!
//! `register()` declares the node and its entities; `on_callback` (and `tick`,
//! where the role has one) is the body. `main.rs`'s `nros::main!()` and the
//! board own init, the executor, RMW registration and the spin loop.

#![no_std]

use core::fmt::Write as _;
use nros::{
    Callback, CallbackCtx, Component, DeclarativeNode, ExecutableNode, NodeContext, NodeOptions,
    NodeResult, TimerDuration,
};
use nros_log::{Logger, log_info};

use std_msgs::msg::String as StringMsg;

/// Talker component — counter state + chatter publish on every tick.
static LOGGER: Logger = Logger::new("@NODE@");

pub struct Talker;

impl Component for Talker {
    const NAME: &'static str = "@NODE@";

    const ENTITY_BOUNDS: nros::EntityBounds = nros::EntityBounds::exact(1, 0, 0, 0, 0);

    fn register(ctx: &mut NodeContext<'_>) -> NodeResult<()> {
        nros_log::register_logger(&LOGGER);
        let mut node = ctx.create_node(NodeOptions::new("@NODE@"))?;
        let pub_chatter = node.create_publisher_for_topic::<StringMsg>("/chatter")?;
        let _timer =
            node.create_timer_for_callback_name("on_tick", TimerDuration::from_millis(1000))?;
        node.callback_for_name("on_tick")
            .publishes_entity(&pub_chatter)?;
        Ok(())
    }
}

impl ExecutableNode for Talker {
    /// Monotonic counter — the next sequence number to publish.
    type State = i32;

    fn init() -> Self::State {
        0
    }

    fn on_callback(state: &mut Self::State, callback: Callback<'_>, ctx: &mut CallbackCtx<'_>) {
        if callback.as_str() == "on_tick" {
            *state = state.wrapping_add(1);
            let mut msg = StringMsg::default();
            let _ = write!(msg.data, "Hello World: {}", *state);
            let _ = ctx.publish_to_topic::<StringMsg, 64>("/chatter", &msg);
            log_info!(&LOGGER, "Publishing: '{}'", msg.data);
        }
    }
}

nros::node!(Talker);
